{"file": "src/packages/cli/src/headless/sdk/session/run-streaming.ts",
 "edits": [
   {"old": "import { handleOrphanedPermissionResponse } from '../../handleOrphanedPermissionResponse.js'",
    "new": "import {
  handleOrphanedPermissionResponse,
  type OrphanedAssistantMessage,
} from '../../handleOrphanedPermissionResponse.js'"},
   {"old": "  // Handle unexpected permission responses by looking up the unresolved tool
  // call in the transcript and executing it
  const handledOrphanedToolUseIds = new Set<string>()
  structuredIO.setUnexpectedResponseCallback(async message => {
    await handleOrphanedPermissionResponse({
      message,
      handledToolUseIds: handledOrphanedToolUseIds,
      onEnqueued: () => {
        // The first message of a session might be the orphaned permission
        // check rather than a user prompt, so kick off the loop.
        void run()
      },
      deps: {
        findUnresolvedToolUse,
        enqueue,
        logDebug: logForDebugging,
      },
    })
  })",
    "new": "  // Handle unexpected permission responses by looking up the unresolved tool
  // call in the transcript and executing it
  const handledOrphanedToolUseIds = new Set<string>()
  // `findUnresolvedToolUse` (sessionStorage) deja `message.id` opcional porque
  // el tipo base de mensaje lo declara asi para toda variante; el mensaje de
  // asistente real que devuelve la transcripcion siempre trae `id` (es la
  // respuesta del API), asi que la guarda de abajo sólo lo confirma antes de
  // adaptarlo al contrato mas estrecho que pide `OrphanedPermissionDeps`.
  const findUnresolvedToolUseForOrphanedPermission = async (
    toolUseID: string,
  ): Promise<OrphanedAssistantMessage | null> => {
    const assistantMessage = await findUnresolvedToolUse(toolUseID)
    if (!assistantMessage || typeof assistantMessage.message.id !== 'string') {
      return null
    }
    return assistantMessage as OrphanedAssistantMessage
  }
  structuredIO.setUnexpectedResponseCallback(async message => {
    await handleOrphanedPermissionResponse({
      message,
      handledToolUseIds: handledOrphanedToolUseIds,
      onEnqueued: () => {
        // The first message of a session might be the orphaned permission
        // check rather than a user prompt, so kick off the loop.
        void run()
      },
      deps: {
        findUnresolvedToolUse: findUnresolvedToolUseForOrphanedPermission,
        enqueue,
        logDebug: logForDebugging,
      },
    })
  })"}
 ],
